[CmdletBinding()]
param(
    [string]$Version
)

$ErrorActionPreference = "Stop"

if (-not $Version) {
    throw "Version parameter is required. Example: pwsh -File scripts/gh_release.ps1 -Version v0.1.1"
}

$repoRoot = Split-Path -Parent $PSScriptRoot
Set-Location $repoRoot

$cleanVer = $Version.TrimStart('v')

$notes = "## AI Proxy Gateway v" + $cleanVer + "`r`n`r`n"
$notes += "### 주요 변경 사항`r`n"
$notes += "- **Skill 지침 주입 — 거버넌스에서 실행으로 (`v0.17.0`)**: 그동안 Skill은 정책·승격·관측 ``대상``이었을 뿐 호출에 실제 적용되지 않았는데, 이제 요청이 `X-Vibe-Skill` 헤더로 **production Skill**을 지정하면 그 **instructions를 system 메시지로 프롬프트 맨 앞에 주입**(X-Vibe-Knowledge 주입과 동일 방식)해 요청이 해당 매뉴얼 하에 실행됨. 파이프라인 `skill` 스텝에서 정책 검사 통과 후 `rc.body`를 재작성(messages 배열이 있는 chat 요청만, 파싱 실패 시 안전 no-op), 적용 시 `X-Vibe-Skill-Applied: 1` 헤더. enforce 모드 차단 시에는 주입 안 함; warn 모드 위반은 헤더 경고 후 주입. 이로써 Skill이 ``governance 객체``에서 ``실행 가능한 능력``으로 완성 — 추천→draft→승격→스캔→**적용**→enforce→관측 루프 완결`r`n"
$notes += "- **OKF 기반 Skill 추천 (`v0.16.0`)**: 반복되는 Text2SQL 질문 패턴(report-candidate 마이너 재사용)에서 **표준화 가능한 Skill 초안을 자동 제안**하는 self-improvement 루프의 Skill판. 신규 API `POST /admin/skills/recommend?window=&min_count=&apply=` — 정규화 질문 빈도가 임계 이상인 클러스터마다 `answer-<slug>` Skill 후보(검증된 SQL 패턴을 instructions에 포함, metadata에 origin/count/데이터상품)를 만들고, **기본은 dry-run(미생성)**·`apply=1`이면 **draft로 멱등 생성**(이미 있는 이름은 재제안 안 함). 추천 Skill은 항상 **draft** — 사람이 검토 후 v0.14.0 승격 게이트·v0.15.0 보안 스캔을 거쳐 production으로 올림(human-in-the-loop, 자동 노출 없음). 어드민 Skills 탭 ``Skill 추천`` 버튼(제안 미리보기 → ``draft로 적용``). 이로써 Skills 에픽이 추천→draft→승격(게이트)→스캔→enforce→관측의 완결 루프를 형성. OpenAPI(`skills` 태그) 반영`r`n"
$notes += "- **Skill 보안 스캐너 + production 보안 게이트 (`v0.15.0`)**: Skill 정의(instructions·metadata·정책 힌트)를 정적 점검하는 보안 스캐너 추가. 탐지: **임베딩 시크릿**(기존 secret firewall 패턴 재사용, 타입만 보고·값 미노출, high)·**프롬프트 인젝션/탈옥 문구**(기존 injection 시그니처 재사용, high)·**파괴적 명령**(rm -rf·DROP TABLE·`| bash`·sudo 등 instructions에 그대로 존재, medium)·**정책 위생**(high-risk인데 allowed_tools 무제한 medium·allowed_models 무제한 low·production인데 instructions 공백 medium). 신규 API `GET /admin/skills/scan?name=`(단건 상세)·`GET /admin/skills/scan`(전체 요약). **승격 게이트 강화**: `to=production` 승격 시 스캔에서 **high 발견이 1건이라도 있으면 422 `security_gate`로 차단**(v0.14.0 전이/instructions/사유 게이트에 보안 게이트 추가). 어드민 Skills 탭 ``보안 스캔`` 버튼(전체 스킬 심각도·발견 요약). OpenAPI(`skills` 태그) 반영`r`n"
$notes += "- **Skill 버저닝·승격 게이트 워크플로 (`v0.14.0`)**: Skill 생애주기 전이를 **검증·기록**하는 거버넌스 경로 추가. 신규 API `POST /admin/skills/promote`{name,to_status,version,note} — **허용 전이만**(draft→staging→production, production/staging→deprecated, deprecated/production→staging 롤백 등; **draft→production 직행 차단** = staging 게이트 필수) 통과시키고, **production 승격 게이트**(instructions 필수, **high-risk는 사유(note) 필수**) 위반 시 422 `promotion_gate`. 전이는 `skill_promotions`(from/to status·version·actor·note) 테이블에 이력으로 적재, 버전 동시 변경 가능. 조회 `GET /admin/skills/promotions?skill=&limit=`. 어드민 Skills 탭 행에 ``승격``·``이력`` 버튼(대상 상태/사유 입력). 기존 `POST /admin/skills` 업서트는 로우레벨 편집용으로 유지하되, **승격은 게이트 경로 권장**. OpenAPI(`skills` 태그) 반영`r`n"
$notes += "- **Skill 실행·비용 관측 대시보드 (`v0.13.0`)**: v0.12.0이 적재하는 `skill_runs`를 Skill별로 집계해 **운영 가시성**을 제공. 신규 API `GET /admin/skills/stats?window=`(기본 30일) — Skill 1개당 실행수·성공(ok)·오류(error)·**차단(blocked)·차단율**·총비용(₩)·평균 지연(ms)·distinct 사용자수·마지막 실행 시각을 busiest 순으로 반환(시간창은 1h/24h/7d/30d 또는 Go duration). 어드민 **Skills 탭 상단에 ``실행·비용 요약`` 표** 추가(차단율은 경고 배지). 집계는 sqlite/PostgreSQL 공통 SQL(GROUP BY + 조건부 SUM)로 수행, OpenAPI(`skills` 태그) 반영. 이제 ``어떤 Skill이 비용을 많이 쓰는지·정책 위반으로 자주 막히는지·실제로 쓰이는지``를 한눈에 점검 가능`r`n"
$notes += "- **Skill 정책 enforce 엔진 (`v0.12.0`)**: v0.11.0 Skill 레지스트리의 `allowed_models`/`allowed_tools` 정책 힌트를 **요청 경로에서 실제로 적용**. 요청이 `X-Vibe-Skill` 헤더로 Skill을 지정하면 게이트웨이가 **선택된 모델·선언된 도구**를 해당 Skill 정책(콤마 구분 glob)과 대조 — 요청 파이프라인에 `skill` 스텝 신설(라우팅 직후·거버넌스 직전 → 모델 재작성 반영). 적용 모드는 런타임 설정 `skills.enforcement`(**off**=비활성·**warn**=위반 시 `X-Vibe-Skill-Policy: warn` 헤더만·**enforce**=위반/비-production Skill 지정 시 403 `skill_policy_violation` 차단, 기본 **warn**으로 안전 롤아웃). 모든 판정은 `skill_runs`에 비동기 기록(차단=blocked·완료=ok/error, 모델·비용·지연·도구 포함; ClickHouse/프록시 요청은 절대 실패시키지 않음). 운영자용 **드라이런** `POST /admin/skills/evaluate`{name,model,tools}(정책 시뮬레이터의 Skill판 — 차단 여부 미리보기)와 **추천 Skill 시드** `POST /admin/skills/seed-recommended`(text2sql-safety-test-generator·prompt-regression-reviewer·mcp-tool-risk-classifier를 draft로 멱등 생성) 추가. 어드민 Skills 탭에 ``추천 Skill 시드`` 버튼·enforce 모드 안내. 설정 권한 그룹은 `security`(security_admin 관할)`r`n"
$notes += "- **Skill 레지스트리 기반 (`v0.11.0`)**: 재사용 가능한 AI 작업 매뉴얼을 거버넌스 대상으로 등록·승격·노출하는 **Skill 레지스트리** 도입(첫 슬라이스). `skills`(name PK·description·version·owner·**status**(draft/staging/production/deprecated)·**risk_level**(low/medium/high)·**allowed_models/allowed_tools** 정책 힌트·instructions·metadata(JSON)·수정 이력)와 `skill_runs`(Skill 실행 로그 — skill·version·actor·input_hash·tools_used·model·status·cost_krw·latency_ms) 테이블 추가. **호출자용 공개 API** `GET /v1/skills`(=production 상태만, 지침 제외 목록)·`GET /v1/skills/{name}`(지침+정책 힌트 포함) — 프록시 키 인증. **관리 API** `GET/POST /admin/skills`(전체 상태 목록·생성/업서트, status·risk·metadata 검증)·`GET|DELETE /admin/skills/by-name/{name}`·`GET /admin/skills/runs?skill=&limit=`(실행 로그). 어드민 **``Skills`` 탭** 신설(상태 필터·등록/편집·삭제·실행 로그 조회), OpenAPI(`skills` 태그)·Swagger 반영. ``production만 외부 노출``로 미검증 Skill 유출 차단, allowed_models/tools는 후속 정책 enforce 엔진의 토대`r`n"
$notes += "- **가격 폴백 모델·환율 런타임 설정화 (`v0.10.8`)**: v0.10.7의 미매칭 모델 폴백을 **런타임에서 조정** 가능하게 함 — 신규 설정 `pricing.fallback_model`(미매칭 모델 과금 기준 모델, 기본 qwen-plus)·`pricing.usd_krw`(카탈로그 시드 환율, 기본 1380). `pricing.fallback_model` 변경은 **재배포 없이 즉시** 비용 계산에 반영(`audit.SetFallbackPriceModel` 원자 적용), `pricing.usd_krw`는 변경 후 `/admin/pricing/seed?overwrite=1` 재시드 시 적용. env(`PRICING_FALLBACK_MODEL`·`PRICING_USD_KRW`)로도 기본값 지정 가능. 어드민 ``런타임 설정``의 `pricing` 카테고리에서 조회·변경`r`n"
$notes += "- **모델 가격 미매칭 시 qwen-plus 단가로 폴백 (`v0.10.7`)**: 가격표에 **정확/프리픽스 매칭이 없는 모델**의 비용을 0으로 처리하던 동작을 변경 — 이제 `qwen-plus` 단가(`audit.FallbackPriceModel`)로 계산. 비용 계산 핵심 경로(`EstimateCostKRW`/`ModelPriced`)와 explain 절감 계산(`lookupModelPrice`) 양쪽에 적용돼 신규/미등록 모델도 합리적 기본가로 과금·집계됨(가격표에 qwen-plus 항목이 있을 때, 없으면 종전대로 0). 특정 모델 단가는 `/admin/pricing` 등록이 항상 우선`r`n"
$notes += "- **ClickHouse 정책 결정 fact 적재 — DW 에픽 완료 (`v0.10.6`)**: `ai_policy_fact` 테이블 추가 — 거버넌스 정책 결정 1건당 1행(request_id·team·endpoint·phase·policy/rule·decision(allow/block/approval)·reason·risk_score·complexity·cost)을 정책 판정 경로에서 **best-effort 적재**(실패 시 retry 큐 보존). bootstrap DDL·런타임 설정 `clickhouse.policy_fact_table`·lag/events 상태에 포함. 이로써 **요청·도구·라우팅·평가·피드백·정책·Text2SQL** 전 영역이 ClickHouse 행동 로그 DW로 적재돼 비용·성능·품질·보안·거버넌스를 요청 단위로 교차 분석 가능 — 일별 rollup 중심에서 ``완전한 행동 로그 DW``로 전환 완료`r`n"
$notes += "- **ClickHouse 사람 피드백 fact 적재 (`v0.10.5`)**: `ai_feedback_fact` 테이블 추가 — `/admin/llm/feedback` 기록 시 피드백 1건당 1행(request_id·trace_id·rating·label·source·created_by)을 **best-effort 직접 적재**(저빈도라 배치 큐 대신 즉시 전송, 실패 시 retry 큐에 보존). bootstrap DDL·런타임 설정 `clickhouse.feedback_fact_table`(미설정 시 비활성)·lag/events 상태에 포함. 이제 ``어떤 모델/프롬프트가 사람 피드백이 나쁜가``를 ai_request_fact·ai_eval_fact와 조인해 분석 가능`r`n"
$notes += "- **ClickHouse Materialized View — 대시보드용 자동 집계 (`v0.10.4`)**: bootstrap이 `ai_request_fact` 위에 **일별·시간별 집계 Materialized View**를 생성 — `<fact>_daily`·`<fact>_hourly`(SummingMergeTree, team·provider·model별 requests·total_tokens·cost_krw·errors)와 이를 채우는 MV(`toStartOfHour(event_time)` 기반 시간 집계 포함). 이제 비용/지연/오류 대시보드 쿼리가 원본 fact 전체 스캔 없이 작은 집계 테이블만 읽어 가볍고 빠름. 요청 fact가 설정된 경우 bootstrap에서 함께 생성`r`n"
$notes += "- **ClickHouse fact 적재 상태 UI + lag/events API (`v0.10.3`)**: 어드민 **ClickHouse 탭에 ``Fact 적재 상태`` 섹션** 추가 — 비동기 큐 깊이/용량/드롭, request_fact 적재 행수와 로컬 요청 수 대비 lag, 재처리 배치 수, 그리고 설정된 fact/rollup 테이블별 **ClickHouse 행수**를 한눈에 표시하고 테이블별 ``최근 보기``로 실제 적재 행을 조회. 신규 API `GET /admin/dw/clickhouse/lag`(테이블별 행수·큐 lag·드롭·retry 집계)·`GET /admin/dw/clickhouse/events?table=&limit=`(설정된 fact 테이블의 최근 행 read-only 조회, 화이트리스트 검증). 운영자가 ``정말 적재되고 있는지``를 즉시 검증 가능`r`n"
$notes += "- **ClickHouse Text2SQL fact 확장 (`v0.10.2`)**: 기존 Text2SQL fact 적재(`CLICKHOUSE_TEXT2SQL_FACT_TABLE`)에 **`reject_reason`(검증 거부 사유)·`sql_hash`(생성 SQL 해시, 원문 미전송)** 컬럼 추가 — ``Text2SQL 실패 원인``(reject_reason·failure_category·schema·mode별)과 동일 SQL 형태 클러스터링 분석 강화. bootstrap DDL·fact sink 동시 확장(질문/SQL 원문은 여전히 미전송, question_chars·sql_hash만)`r`n"
$notes += "- **ClickHouse 세부 이벤트 fact 분리 적재 — tool·routing·eval (`v0.10.1`)**: v0.10.0의 비동기 fact 파이프라인을 확장해 **`ai_tool_fact`(MCP/도구 호출 1건당 1행: server·tool·source·is_mcp·is_error·arg_hash)·`ai_routing_fact`(요청당 1행: 요청/선택 모델·provider·complexity·risk·health·fallback_path·decision_reason)·`ai_eval_fact`(LLM 평가 1건당 1행: name·category·score·label·passed)** 를 **같은 요청 큐에서 한 번에 fan-out** 적재(요청당 추가 비용 없음, 각 테이블 독립 INSERT·독립 retry). routing/eval은 `ReplacingMergeTree`로 멱등, tool은 append. bootstrap이 세 DDL 자동 생성, 런타임 설정 `clickhouse.tool_fact_table`·`routing_fact_table`·`eval_fact_table`로 개별 on/off(미설정 시 비활성). 이제 ``어떤 MCP 도구가 위험한가``·``자동 라우팅이 비용을 줄였나``·``어떤 프롬프트 버전 품질이 낮은가``를 ClickHouse에서 직접 분석 가능`r`n"
$notes += "- **ClickHouse 요청 단위 fact 적재 (행동 로그 DW) (`v0.10.0`)**: 기존 일별 rollup sink는 그대로 유지하면서, **요청 1건당 1행**을 ClickHouse `ai_request_fact`로 보내는 **비동기 배치 파이프라인** 추가 — 팀·모델·provider·프로젝트·프롬프트·라우팅·토큰·비용·지연·오류를 요청 단위로 분석 가능. 요청 경로에서 직접 호출하지 않고 내부 **bounded 큐 → 배치 flush**(`clickhouse.batch_size`·`clickhouse.flush_interval`, 큐 가득 시 드롭 카운트), `ReplacingMergeTree(ingested_at)` + `ORDER BY (event_date,team,provider,model,request_id)`로 **재전송 멱등**, `JSONEachRow`에 `best_effort`+`skip_unknown_fields` 적용. **개인정보 보호**: 프롬프트/응답 원문 미전송, client IP는 해시. ClickHouse 장애 시 요청은 실패하지 않고 실패 배치는 `clickhouse_fact_retry`에 저장→`POST /admin/dw/clickhouse/fact-retry`로 재처리. `clickhouse.request_fact_table` 설정 시 활성화(미설정 시 완전 비활성), bootstrap이 `ai_request_fact` DDL 생성, overview에 큐 깊이·드롭·retry 노출`r`n"
$notes += "- **ClickHouse 수동 적재 — 집계 후 전송 (`v0.9.9`)**: ``지금 적재``(`POST /admin/dw/clickhouse`)가 로컬 일별 rollup을 **읽기만** 하고 집계는 안 해서, 보존 워커(기본 1h)가 아직 안 돌았거나 당일 rollup이 비어 있으면 트래픽이 있어도 ``적재 완료 0행``이 뜨던 문제 수정. 이제 적재 전에 해당 기간을 **`RollupRange`로 먼저 집계**한 뒤 전송하므로 버튼만으로 현재 데이터가 반영됨. 참고: DW로 보내는 데이터는 일별 집계 행(`day·dimension(all/model/provider/project/cost_center)·dim_value·requests·tokens·cost_krw·errors`)이며, fact 테이블 설정 시 Text2SQL 질의 단위 fact도 전송`r`n"
$notes += "- **OpenAPI 전체 API 망라 (`v0.9.8`)**: `/openapi.json`을 큐레이션 subset에서 **전체 HTTP 서피스 망라**로 확장 — 라우트 등록 목록과 동기화된 엔드포인트 카탈로그(`apiEndpoints`)에서 스펙을 코드로 생성(135+ 경로). inference·auth·self-service·admin·settings·cost·routing·governance·text2sql·okf·dw·llm·mcp·vcs·notifications 태그로 그룹화, 경로 파라미터(`{id}`/`{key}`/`{name}`/`{server}`/`{team}`/`{user_id}`)·메서드(GET/POST/PUT/PATCH/DELETE)·보안(공개 vs bearerAuth) 표기. Swagger UI(`/swagger`)에서 전 API 탐색 가능`r`n"
$notes += "- **어드민 UX — 마지막 사용자 메시지·앱 버전·세션 만료·API 문서 (`v0.9.7`)**: (1) **요청 상세 모달** 최상단(요청 ID 위)에 **마지막 사용자 메시지**를 가독성 높은 강조 카드로 표시(마크다운 렌더). (2) 개인 메뉴의 **단축키 도움말 아래에 앱 버전**(`__APP_VERSION__`, 서버 주입)을 노출. (3) **로그아웃 버튼 아래에 세션 만료 예정 시각**(access token exp, `/auth/me`의 `expires_at` 기반, 남은 분 표시). (4) 개인 메뉴에 **Swagger API 페이지(`/swagger`)와 `openapi.json` 링크** 추가 — 공개 GET `/openapi.json`(주요 엔드포인트 큐레이션 스펙, info.version=앱 버전)·`/swagger`(Swagger UI, 폐쇄망에서는 openapi.json 직접 사용 안내)`r`n"
$notes += "- **OKF 게이트웨이 지식그래프 + 에이전트 자기개선 루프 (`v0.9.6`)**: (1) **지식그래프 sync**(`POST /admin/okf/graph/sync`) — API Key→소유자(user)·소속팀(team), 모델 glob→서빙 업스트림(`served_by`) 관계를 OKF 링크로 구성해 ``왜 이 요청이 이 모델/업스트림으로 갔는지``를 설명 가능하게 함(엔티티 문서 + 엣지 자동 생성, 멱등). (2) **자기개선 루프**(`POST /admin/okf/propose?window=&min_count=`) — 반복되는 Text2SQL 질문(report candidate)을 **status=proposed** OKF sample_sql 문서로 자동 제안하고, 사람이 검토 후 status=active로 재저장하면 활성 지식이 됨(자동 반영 없음 — human-in-the-loop). 이로써 프록시가 조직 AI 컨텍스트 허브로서 스스로 지식을 축적`r`n"
$notes += "- **Text2SQL OKF 메타지식 주입 (`v0.9.5`)**: OKF 지식을 Text2SQL 프롬프트에 연결해 정확도↑·hallucination↓. SQL 생성 프롬프트에 **요청 허용 테이블로 스코프된** OKF 메타지식 블록(테이블 설명·조인 경로·금지/주의 쿼리 패턴·샘플 SQL·추가 지침)을 스키마 컨텍스트 바로 뒤에 주입(`WithOKFKnowledge`). 스키마 레지스트리·골든쿼리로부터 OKF 문서를 자동 생성하는 시드 API `POST /admin/okf/text2sql/sync?schema=`(테이블/컬럼 설명→table/column 문서, 골든→sample_sql 문서, 멱등) 추가. **OKF 문서가 없으면 완전 no-op**이라 무설정 안전, 큐레이션할수록 생성 품질이 올라감`r`n"
$notes += "- **OKF 지식 기반 — 문서·링크·Export/Import (`v0.9.4`)**: 조직 AI 컨텍스트를 **OKF(Open Knowledge Format)** 로 관리하는 기반 도입. `okf_documents`(kind=table/column/join_path/forbidden_query/sample_sql/model_policy/entity/glossary 등 + subject·title·body·attributes(JSON)·tags·status)와 `okf_links`(from–relation–to 지식그래프 엣지) 테이블 + CRUD API(`GET/POST /admin/okf/documents`, `GET/DELETE …/by-id/{id}`, `GET/POST /admin/okf/links`). **Export**(`GET /admin/okf/export?kind=&subject=&tag=&status=` — 매칭 문서 + 연결 링크를 portable 번들로)와 **Import**(`POST /admin/okf/import` — 외부 DB 문서·업무 규칙·모델 정책 번들 가져오기, (kind,subject)·(from,relation,to) 키로 멱등). 이후 Text2SQL 메타지식 주입·게이트웨이 지식그래프·자기개선 루프의 공통 저장소`r`n"
$notes += "- **모델 가격표 현재가 자동 시드 (`v0.9.3`)**: 내장 가격 카탈로그를 **현행 모델 ID**(Claude Opus 4.8/4.7/4.6·Sonnet 4.6/4.5·Haiku 4.5·Fable 5, GPT-5.x·4o·o3·o4-mini, Gemini 3, Qwen/Kimi 등)로 갱신하고, **첫 기동 시 가격 테이블이 비어 있으면 카탈로그를 자동 적용**(`seedPricingIfEmpty`). 이제 별도 시드 호출 없이도 합리적인 현재가가 미리 들어가 비용 계산이 바로 동작하며, 운영자는 `POST /admin/pricing`(모델별 새 버전)·`/admin/pricing/seed?overwrite=1`(카탈로그 재적용)로 언제든 덮어쓸 수 있음(버전 이력 유지). 기존 관리 가격이 있으면 부팅 시 절대 건드리지 않음`r`n"
$notes += "- **시맨틱 캐시 — 멀티턴 자동 스킵 게이팅 (`v0.9.2`)**: 시맨틱 chat 캐시가 **단발성(single-turn) 요청에만** 동작하도록 게이팅. 시맨틱 캐시는 messages 배열 **전체**를 임베딩해 코사인 유사도로 비교하는데, 멀티턴 에이전트 대화는 맥락이 계속 누적돼 (1) 이전 엔트리와 거의 적중하지 않아 임베딩 호출만 낭비되고 (2) 우연히 적중하면 다른 맥락의 답을 줄 위험이 있음. 이제 assistant/tool 턴이 있거나 tools가 선언된 요청은 임베딩을 **건너뜀**(저장도 안 함) — 같은 질문 재요청 같은 안전·고확률 케이스에만 캐시가 동작. 멀티턴까지 강제로 켜려면 신규 런타임 설정 `cache.chat_semantic_multiturn=true`(기본 off). 임베딩 비용 낭비 제거 + 오적중 방지`r`n"
$notes += "- **ClickHouse 설정·모니터링 콘솔 (`v0.9.1`)**: 어드민에 **ClickHouse 탭** 신설 — 한 화면에서 연결 상태(ping·지연), rollup 테이블 존재/엔진/dedupe 키 점검, 자동 적재 on/off·주기, dimension별 적재 워터마크, 실패 재처리 대기열을 보여주고 **연결 테스트·테이블 생성·지금 적재·실패분 재처리·정합성 확인** 버튼을 제공. 신규 API `POST /admin/dw/clickhouse/bootstrap`(rollup·fact 테이블을 ``IF NOT EXISTS``로 자동 생성 — ReplacingMergeTree + (day,dimension,dim_value) 정렬키 보장)·`GET /admin/dw/clickhouse/overview`(단일 호출 상태 집계). 또한 Text2SQL fact 적재 시 RFC3339 타임스탬프가 DateTime 컬럼에 들어가도록 ``date_time_input_format=best_effort`` 적용. 이제 운영자가 DDL을 수기로 작성하거나 curl 없이 설정→생성→적재→검증을 클릭으로 수행`r`n"
$notes += "- **시맨틱 캐시 — 임베딩 전용 프로바이더/URL (`v0.9.0`)**: 시맨틱 chat 캐시의 임베딩 호출 대상을 분리할 수 있게 함. 기존에는 임베딩이 일반 chat과 동일한 프로바이더 선택(모델 glob→기본 업스트림)을 그대로 타서 별도 URL 지정이 불가능했음. 신규 설정 `cache.embedding_base_url`(설정 시 ``{base_url}/v1/embeddings``로 **직접 호출** — 예: 사내 로컬 임베딩 서버)·`cache.embedding_provider`(임베딩에 강제할 등록 프로바이더)·`cache.embedding_api_key`(전용 키, 암호화 저장·마스킹) 추가. **세 값이 모두 비어 있으면 기존 동작 그대로**(프로바이더 라우팅) 유지하고, base_url만 주고 key를 비우면 기본 업스트림 키로 폴백. 런타임 설정이라 재배포 없이 즉시 반영`r`n"
$notes += "- **프록시 API 키 — 팀 ID를 팀명으로 표기 (`v0.8.9`)**: 사용자(Proxy API 키) 목록·상세에서 팀이 **팀 ID**(예: `team_security`)로 보이던 문제 수정. 셀프서비스(``내 키``)로 발급한 키는 사용자 정체성의 팀 ID를 저장하는데, 어드민 화면이 그 값을 그대로 출력해 ID가 노출됐음. 이제 `/admin/users`(목록·상세) 응답에 `auth_teams` 기반 `team_names`(ID→표시명) 매핑을 포함하고, UI는 **팀 표시명을 크게·ID를 작은 글씨**로 렌더(`#/teams/{id}` 링크·필터는 ID 유지). 매칭되는 auth team이 없는 자유 입력 팀은 기존처럼 입력값 그대로 표기`r`n"
$notes += "- **런타임 관리자 설정 — 키별 상세 설명 (`v0.8.8`)**: 런타임 설정 화면의 각 설정 키에 **무엇을 바꾸는지 한 줄 도움말**을 작은 글씨로 표기 — ClickHouse·Text2SQL·Carbon·Insurance·Cache·Retention 전 키(50여 개)에 대해 용도·단위·예시·재연결 영향(예: ``자동 적재 주기(예: 1h). 변경 시 sink 워커 재시작``)을 키 코드 아래 회색 캡션으로 노출. 설명은 API 응답에도 `description` 필드로 포함되어 외부 도구·문서화에서 재사용 가능. 운영자가 키 이름만 보고 추측하지 않도록 함`r`n"
$notes += "- **런타임 관리자 설정 — 역할별 권한 (`v0.8.7`)**: 런타임 설정 쓰기를 역할 범위로 제한(스펙 §11) — 설정 전용 서브 관리자 역할 `ops_admin`(ClickHouse·Retention·Cache)·`ai_admin`(Text2SQL 모델·dialect·shadow·clarify 등)·`security_admin`(마스킹·일일 위험 한도/경고·Replay 보존·모든 **secret** 키)을 추가하고, 각 설정 키를 **권한 그룹**(secret 및 mask_results·daily_risk_limit/warn·replay_bundles→`security`, ClickHouse/Retention/Cache→`ops`, 그 외 Text2SQL→`ai`, Carbon/Insurance→`admin`)으로 분류. 서브 관리자는 `admin:read`만 보유해 다른 어드민 엔드포인트는 못 쓰고, `/admin/settings` 하위에서 **자기 그룹만** 쓰기 가능(PUT·DELETE·bulk·import·rollback 모두 키 단위로 검증해 위반 시 403 `settings_role_denied`/422). `admin`·`super_admin`(및 토큰 모드)은 전체 쓰기 유지, `readonly_admin`은 읽기·이력만. 설정 목록 응답에 키별 `permission_group`·`can_write` 노출`r`n"
$notes += "- **런타임 관리자 설정 — 일괄 적용·내보내기/가져오기 (`v0.8.6`)**: GitOps 친화 일괄 API 추가 — `PUT /admin/settings/bulk`(여러 설정 원자 적용: 전체 검증 후 일괄 쓰기·1회 reload, 하나라도 실패하면 전부 미적용으로 부분 적용 장애 방지), `GET /admin/settings/export`(admin 오버레이 중 **비밀값 제외** 키·값을 import 가능한 형식으로), `POST /admin/settings/import`(export 형식 가져오기, **secret 키는 거부**하고 개별 설정 요구). default_limit<=max_limit 교차 검증 포함`r`n"
$notes += "- **런타임 관리자 설정 — Cache·Retention 확장 (`v0.8.5`)**: 레지스트리에 **Cache**(embedding/chat/semantic on·off·TTL·임계값 등 9키)와 **Retention**(request/prompt/response/text2sql_replay days·interval 5키) 추가 — Cache는 `s.cacheConf()` 오버레이로 다음 요청부터 즉시 반영, Retention은 워커를 **런타임 reconfigure** 가능하게 리팩터(일수는 다음 실행부터, interval 변경 시 ticker 재생성, atomic 보호)해 재배포 없이 보관정책 변경. 변경 이력·롤백·연결 무관 검증 그대로`r`n"
$notes += "- **런타임 관리자 설정 — Carbon·Insurance 확장 (`v0.8.4`)**: 런타임 설정 레지스트리를 **Carbon(탄소 점수 계수)·Insurance(SLA 기준)** 카테고리로 확장 — `carbon.wh_per_1k_tokens`·`carbon.pue`·`carbon.grid_intensity_g`, `insurance.sla_target`·`insurance.fast_burn`·`insurance.slow_burn`를 어드민 화면에서 조회·변경하면 atomic 스냅샷(`s.carbonConf()`/`s.insuranceConf()`)으로 즉시 반영되어 Prompt Carbon Score·AI 요청 보험/번레이트 리포트의 계산 기준이 재배포 없이 갱신(검증: rate 0~1, 양수/음수 제약). 변경 이력·롤백은 기존 설정 백엔드 그대로 적용`r`n"
$notes += "- **런타임 관리자 설정 — 어드민 UI (`v0.8.3`)**: 어드민 대시보드에 **런타임 설정** 탭 추가 — ClickHouse·Text2SQL 설정을 카테고리별 표로 조회·편집(값 입력/불리언 select)·저장(즉시 반영), 출처(env/admin)·재연결 필요 배지 표시, 민감값은 마스킹 입력(빈 값이면 변경 안 함), 기본값 되돌리기·롤백·키별 변경 이력 보기, ClickHouse/실행 DB/Twin DB **연결 테스트 버튼** 내장. 운영자가 curl 없이 v0.8.0~0.8.2 설정 백엔드를 다룰 수 있음`r`n"
$notes += "- **런타임 관리자 설정 — 커넥션 스왑·워커 재시작·연결 테스트 (`v0.8.2`)**: 설정 변경의 런타임 적용을 커넥션/워커까지 확장 — (1) Text2SQL **Exec/Twin DSN·드라이버 변경 시 캐시된 `sql.DB`를 close하고 다음 요청에서 새 대상으로 재오픈**(swap), (2) ClickHouse **sink worker를 관리형으로 전환**해 URL·interval 변경 시 안전하게 stop/start/restart(빈 URL·0 interval이면 중지), (3) 적용 전 **연결 테스트 API**(`POST /admin/settings/test/clickhouse`·`/text2sql-exec`·`/text2sql-twin`) — ClickHouse SELECT 1 ping + 테이블 존재 확인, 실행/트윈 DB open+SELECT 1, twin이 exec와 동일 DSN이면 경고. 본문에 후보값(url·dsn 등)을 주면 저장 전에 검증 가능`r`n"
$notes += "- **런타임 관리자 설정 — Text2SQL/ClickHouse 즉시 반영 (`v0.8.1`)**: v0.8.0 설정 저장소를 **런타임 스냅샷**에 연결 — 서버는 부팅 시와 설정 변경 시마다 ``env 기본값 + DB 관리자 오버레이``를 atomic 스냅샷(`s.t2sConf()`/`s.chConf()`)으로 재구성하고, Text2SQL 핸들러·스케줄러·파이프라인과 ClickHouse sink가 이를 참조하도록 변경. 이제 모델·limit·mask·dialect·clarify·shadow·risk 등 Text2SQL 설정과 ClickHouse DB/table/계정/fact table 등은 **재배포 없이 다음 요청·다음 적재부터** 적용(민감값은 스냅샷 구성 시 복호화해 메모리에서만 사용). ※ Exec/Twin DSN 핫스왑과 sink worker interval·URL 변경 시 재시작은 v0.8.2`r`n"
$notes += "- **런타임 관리자 설정 — 기반 (`v0.8.0`)**: 그동안 환경변수로만 지정하던 ClickHouse·Text2SQL 설정을 **관리자 화면에서 조회·변경·검증·이력·롤백**할 수 있는 기반 도입(`env 기본값 + DB 관리자 오버레이` 구조의 1단계) — 설정 레지스트리(키별 카테고리·타입·secret 여부·검증기), `admin_settings`/`admin_setting_history` 테이블, API(`GET /admin/settings`·`/{category}`, `PUT/DELETE /admin/settings/by-key/{key}`, `POST /admin/settings/validate`·`/rollback`, `GET /admin/settings/history`). **민감값(DSN·password)은 GATEWAY_SECRET으로 암호화 저장하고 응답에서 ``********`` 마스킹**, 변경 이력(이전/이후)과 롤백, default_limit<=max_limit 등 교차 검증 포함. ※ 본 단계는 저장·검증·이력 기반이며 런타임 즉시 반영(워커 재시작·DSN swap)은 후속 릴리스에서 연결`r`n"
$notes += "- **엔터프라이즈 종합 기술 보고서 개정 및 공식 릴리즈 배포 (`v0.7.5`)**: 40여 종의 신규 시스템 환경변수(시맨틱 캐시, 셀프서비스 키, Text2SQL 파이프라인, Carbon ESG, SLA 보험, ClickHouse 싱크 등)를 표에 완벽히 추가 수록하고, 18대 서브시스템 아키텍처 수립 및 v0.7.5 최종 릴리즈 패키징 완료`r`n"
$notes += "- **개인 메뉴 정리·콘텐츠 여백 (`v0.7.4`)**: 로그아웃 버튼을 개인 메뉴 내 ``내 키`` 아래로 이동(헤더 정리), 그리고 ``내 키``·``개인화``·``사용 한도`` 패널의 콘텐츠 영역에 들여쓰기 여백(`card-body` 패딩) 적용으로 가독성 향상`r`n"
$notes += "- **개인 메뉴(auth-user 드롭다운) (`v0.7.3`)**: 상단 nav를 정리하고 **사용자 칩(`auth-user`) 클릭 시 드롭다운**으로 개인 메뉴 노출 — 개인화·내 키 이동, 자동 새로고침 주기·테마 전환·단축키 도움말을 한 곳에. 토큰 모드에서도 칩이 ``☰ 메뉴`` 트리거로 항상 표시되어 접근 가능, 외부 클릭/Esc로 닫힘`r`n"
$notes += "- **만료·미사용 키 알림 (`v0.7.2`)**: API Key 위생 점검 — 활성 키 중 **만료 임박/만료됨/미사용/장기 유휴**를 탐지(`GET /admin/keys/health?stale_days=&expiring_days=`, 기본 30·7일). 키별 flags(expired/expiring_soon/never_used/stale_unused)·severity(high/medium)·유휴일수, request_logs로 마지막 사용 시점 산출, 위험 큰 순 정렬. My AI Home 대시보드(`/me/dashboard`)에 **본인 키 알림** 섹션 추가. read-only`r`n"
$notes += "- **내 키 패널 UI (`v0.7.1`)**: 어드민 대시보드에 **``내 키``** 탭 추가 — 로그인 주체 본인의 API Key를 화면에서 발급/회전/폐기(`/me/keys` 연동). 발급/회전 시 평문 시크릿을 1회 배너로 표시(복사용), 스코프는 비우면 본인 권한 상속·입력 시 본인 범위 내로 제한. 셀프서비스 비활성(`SELF_SERVICE_KEYS_ENABLED=false`) 또는 사용자 식별 불가 시 안내 메시지`r`n"
$notes += "- **셀프서비스 키 관리 (`v0.7.0`)**: 사용자가 **본인 소유 API Key를 직접 관리**하는 opt-in 경로(`SELF_SERVICE_KEYS_ENABLED`, 기본 off) — `GET/POST /me/keys`(본인 키 목록·발급), `POST /me/keys/{id}/rotate`(회전), `DELETE /me/keys/{id}`(폐기). 호출자는 JWT(sub) 또는 API Key(user_id)로 식별, 발급 키는 **본인 role·스코프 이내로만**(권한 상승 차단, 미지정 시 본인 스코프 상속), 타인 키는 404로 은닉. 평문 시크릿은 발급/회전 시 1회만 반환, 모든 동작 감사 로그 기록`r`n"
$notes += "- **프로필 스냅샷 추세 (drift) (`v0.6.9`)**: Personal AI Profile 스냅샷(v0.6.5)을 시점 비교해 사용 패턴 변화를 드러냄 — 최근 2개 스냅샷 간 요청수·총비용·요청당 평균비용·성공률 델타와 대표 모델/주요 작업 전환을 계산하고 `cost_up`/`cost_down`/`success_down`/`model_shift`/`task_shift` 신호 부여. 프로필 상세 응답에 `drift` 포함 + 전용 조회(`GET /admin/personalization/profiles/{user_id}/drift`), 어드민 ``개인화`` 탭 상세에 추세 카드 표시. 스냅샷 2개 미만이면 baseline 없음`r`n"
$notes += "- **추천 채택률 추적 (`v0.6.8`)**: My AI Home 추천(v0.6.6)에 대한 사용자 피드백을 기록·집계 — 사용자가 추천을 **채택/거절**(`POST /me/recommendations/feedback {id, action}`, 추천의 kind·ref에 키잉)하면 `recommendation_feedback`에 저장, 관리자는 종류별 채택/거절·distinct 채택자·채택률(adopted/(adopted+dismissed))을 조회(`GET /admin/recommendations/adoption?window=`). 추천이 실제로 행동으로 이어지는지 측정. 추천 레코드에 `ref`(추천 모델/템플릿 id) 추가`r`n"
$notes += "- **개인화 어드민 UI (`v0.6.7`)**: Personal AI Profile(v0.6.5)을 어드민 대시보드에 **새 ``개인화`` 탭**으로 노출 — 사용자별 프로필 목록(요청·총비용·성공률·대표 모델·주요 작업·요약, 정렬 가능)과 상세 화면(팀/역할, 비용 성향, 선호 작업/모델/언어, 스냅샷 이력 + ``스냅샷 생성`` 버튼). 운영자가 curl 없이 사용자 사용 패턴을 검토하고 시점 스냅샷을 남길 수 있음`r`n"
$notes += "- **My AI Home (`v0.6.6`)**: 관리자 대시보드와 별개로 **사용자 본인이 자신의 AI 사용 현황을 보는** self-service 화면(`GET /me/dashboard`, `GET /me/recommendations`) — 호출자를 JWT(sub) 또는 API Key(user_id)로 식별. 대시보드: 오늘 사용량·이번 달 비용/요청·자주 쓰는 모델·최근 실패 요청·절감 가능 금액(본인 최저비용-충분 모델로 환산)·추천 템플릿·최근 Prompt Product. 추천: 본인 사용 패턴 기반 모델 전환(절감액 포함)·표준 템플릿 채택 제안을 생성·`personal_recommendations`에 저장. 사용자가 스스로 비용·품질을 개선`r`n"
$notes += "- **Personal AI Profile (`v0.6.5`)**: 사용자별 AI 사용 프로필을 로그에서 산출하는 read-only 기능(`GET /admin/personalization/profiles`, `GET /admin/personalization/profiles/{user_id}`) — api_key→user 매핑으로 팀·역할, 요청량·총비용·요청당 평균비용, 성공/오류율, 선호 task_type·모델·언어(Top5), distinct 모델/프롬프트지문, 한 줄 요약(예: ``주로 refactor, sql_analysis를 수행하며 gpt-4.1-mini 선호, 성공률 86%``)을 집계. 상세 조회 시 최신 프로필을 `personal_profiles`에 캐시하고 `?snapshot=1`이면 `personal_profile_snapshots`에 시점 스냅샷 기록. 이후 라우팅·템플릿 추천·Text2SQL 힌트·비용 코칭의 기준점`r`n"
$notes += "- **관리자 감사 이상탐지 (`v0.6.4`)**: 관리자 감사 로그에서 의심 패턴을 탐지하는 read-only 분석(`/admin/audit/anomalies?window=&destructive=&volume=`) — admin별 **파괴적 액션 버스트**(delete/revoke/remove/hard, 기본 5건↑), **권한/스코프 변경**(scope/role/grant/permission/escalat), **업무외 시간 활동**(22:00–06:00 UTC), **고볼륨**(기본 100건↑)을 집계해 flags + severity(high/medium) 부여, 위험 큰 순 정렬. sqlite/pg 공통(시간 분석은 앱에서 수행), 강제 없음`r`n"
$notes += "- **비용센터 청구서 (`v0.6.3`)**: cost_center별 AI 사용료 **chargeback 청구서** 생성(`/admin/invoices?cost_center=&window=&format=`) — 지정 시 해당 센터의 모델별 라인아이템(요청·토큰·비용)+합계를 JSON 또는 **markdown 청구서**(`format=markdown`, 티켓·위키·Mattermost 붙여넣기용)로 반환, 미지정 시 전체 cost_center 요약 목록. 기존 비용 배부 데이터 재사용, read-only`r`n"
$notes += "- **모델 마이그레이션 어드바이저 (`v0.6.2`)**: 프롬프트 지문 클러스터별로 **지배 모델 → 더 싸고 충분히 좋은 모델** 전환을 추천하는 read-only 어드바이저(`/admin/model-migration?window=&min_requests=`) — 동일 프롬프트 형태에서 관측된 모델별 평균비용·성공률을 비교해, 최고 성공률 대비 5pp 이내이면서 더 싼 모델을 후보로 제시하고 ``클러스터 요청수×(현재−추천 평균비용)``으로 절감액 추정. 최소 요청수(기본 20) 미만 클러스터·단일 모델 클러스터는 제외, 절감액 큰 순 정렬`r`n"
$notes += "- **에러버짓 번레이트 (`v0.6.1`)**: SLA claim 정의(4xx/5xx/failover/error) 위에 **멀티윈도우 에러버짓 소진율** 산출(`/admin/insurance/burn-rate?dimension=&window=&short=&sla=`) — scope별 short(기본 1h)·long(기본 24h) 윈도우의 claim_rate를 허용치(`1-SLA`)로 나눈 burn rate, Google SRE 패턴대로 두 윈도우 모두 ``fast``(기본 14.4×, page) / long만 ``slow``(기본 3×, ticket) 분류 + 30일 버짓 기준 ``소진까지 일수``(=30/long burn) 투영. 임계값 `INSURANCE_FAST_BURN`/`INSURANCE_SLOW_BURN` 또는 `?fast=&slow=` 오버라이드. 위험 큰 순 정렬`r`n"
$notes += "- **절감 리포트 (Savings Report) (`v0.6.0`)**: 게이트웨이가 만들어낸 비용 절감을 scope별로 정량화하는 read-only 리포트(`/admin/savings?dimension=&window=`) — **라우팅 다운시프트 절감**(요청 모델보다 싼 모델로 서빙된 요청을 ``요청 모델 가격으로 환산한 baseline − 실제 비용``으로 정확 산출)과 **캐시 절감**(route_reason=cache 적중 × 동일 scope 비캐시 평균 비용으로 추정)을 합산. scope별 다운시프트 요청수·절감액·캐시 적중·캐시 절감(추정)·총 절감액 + 전체 합계. 게이트웨이 ROI를 숫자로 증명`r`n"
$notes += "- **AI 요청 보험 모드 (SLA claims) (`v0.5.9`)**: 보장 범위(scope)별 요청을 ``covered``로, 저하된 결과(4xx/5xx/failover/error)를 ``claim``으로 보고 SLA 목표 대비 위반을 드러내는 read-only 원장(`/admin/insurance/claims?dimension=&window=&sla=`) — scope별 covered·claims(+5xx/4xx/failover 진단 분해)·claim_rate·신뢰도, SLA 허용치(`(1-목표)*covered`) 대비 초과 claim(excess=위반 규모)와 sla_met 산출, 위반 큰 순 정렬. 목표는 `INSURANCE_SLA_TARGET`(기본 0.99) 또는 `?sla=` 오버라이드. 강제 없음`r`n"
$notes += "- **Prompt to Product (`v0.5.8`)**: 반복되는 chat 프롬프트(프롬프트 지문 클러스터)를 **재사용 가능한 명명된 템플릿(제품)** 으로 승격하는 전체 루프 — 후보 발굴(`GET /admin/prompt-products/candidates` : 기존 프롬프트 지문 분석 재사용, 빈도·비용·대표/최저비용 모델·샘플 + 이미 제품화 여부 표시), 승격(`POST /admin/prompt-products` : 정식 템플릿 생성 + 출처 지문·승격 시점 reach(요청수·distinct 사용자) 스냅샷 기록), 목록(채택도=템플릿 use_count·last_used 조인), 삭제. 원천 프롬프트 로그가 없어도(LOG_RAW_PROMPTS off) 관리자가 정식 템플릿 본문을 작성해 자산화. 새 의존성 없음`r`n"
$notes += "- **Golden Workflow (`v0.5.7`)**: 여러 골든 스텝을 **순서가 있는 하나의 회귀 단위**로 묶어 실행하는 1급 엔터티(`/admin/golden-workflows` CRUD, `/admin/golden-workflows/run`) — 단발 Golden Prompt나 임의 태그 그룹과 달리 워크플로우는 이름·설명·정렬된 스텝(각 prompt+expected)을 갖고, 실행 시 스텝별 통과/점수와 전체 pass_rate를 반환. `?fail_on_regression=1`+`min_pass_rate`로 CI 게이트 사용(미달 시 422). 스텝 간 출력 체이닝은 의도적으로 제외(단순 회귀 스위트). 새 의존성 없음`r`n"
$notes += "- **AI 업무지도 (Work Map) (`v0.5.6`)**: ``어떤 AI 업무가 어디서 누구에 의해 일어나는가``를 한 화면에 모으는 read-only 통합 뷰(`/admin/work-map?dimension=&window=`) — work 차원(기본 project, repo·team·service 등)별로 요청량·토큰·비용·distinct 사용자/모델·오류율·대표 모델과 **task_type(generate/refactor/debug 등) 분포**를 노드 단위로 집계. 단일 지표인 비용 배부, 신뢰도 중심의 신용점수와 달리 ``업무의 성격``까지 한눈에. 새 의존성·계약 변경 없음`r`n"
$notes += "- **Prompt Carbon Score (`v0.5.5`)**: 이미 적재된 토큰 사용량으로 요청의 **전력(Wh)·운영 탄소(gCO2e)** 를 추정하는 read-only 분석(`/admin/carbon-score?dimension=&window=`) — subject(model·project·api_key 등)별 토큰량에 모델별 에너지 계수를 적용해 에너지/배출/요청당 Wh 산출. 계수는 전부 설정값(`CARBON_WH_PER_1K_TOKENS` 기본 0.4Wh/1K, `CARBON_MODEL_WH_PER_1K`=model별 오버라이드, `CARBON_PUE` 기본 1.2, `CARBON_GRID_INTENSITY_G` 기본 475 gCO2e/kWh)이며, 공개 추정치 편차가 커 **절대값이 아닌 주체 간 상대 비교 신호**로 사용. 강제 없음`r`n"
$notes += "- **SQL Digital Twin (`v0.5.4`)**: Golden Query **결과 동등성 검증**을 운영 DB 대신 마스킹·샘플 **트윈 DB**에서 실행하는 opt-in 경로 추가 — `TEXT2SQL_TWIN_DSN`(+`TEXT2SQL_TWIN_DRIVER`, 기본 postgres) 설정 시 기대/생성 SQL 비교를 트윈에서 수행해 프로덕션 데이터 노출 없이 검증 가능, 미설정 시 기존 실행 DB로 그대로 폴백(동작 변화 없음). 트윈 커넥션은 지연 오픈·캐시(read-only 검증 전용)`r`n"
$notes += "- **사내 AI 신용점수 (`v0.5.3`)**: subject(API Key·project·model 등)별 **신용점수**(`/admin/ai-credit-score?dimension=&window=`) — 신뢰도(성공률 0.7)+비용효율(상대 cost/req 0.3) 블렌드 0~100, 표본 5건 미만은 low-confidence 표시. 안전/비용 효율이 좋은 주체를 한눈에(read-only, 강제 없음)`r`n"
$notes += "- **데이터 상품 추천 (`v0.5.2`)**: 반복 Text2SQL 질문(report candidate)에 SQL 형태 기반 **추천 산출물 분류** 추가 — 집계 쿼리→`dashboard`, 다중 JOIN→`data_mart`, 단건/목록 조회→`api`. 어드민 인사이트 표에 노출되어 반복 질문을 어떤 데이터 상품으로 만들지 판단 보조`r`n"
$notes += "- **시맨틱(임베딩) chat 캐시 (`v0.5.1`)**: 정확 캐시(temp 0/seed) miss 시 프롬프트를 임베딩해 코사인 유사도로 근사 응답을 재사용하는 opt-in 캐시 — `CACHE_CHAT_SEMANTIC_ENABLED`+`CACHE_CHAT_SEMANTIC_MODEL`(임베딩 모델) 필요, `CACHE_CHAT_SEMANTIC_THRESHOLD`(기본 0.95)·`CACHE_CHAT_SEMANTIC_MAX_CANDIDATES`(기본 200). 임베딩 호출 실패 시 정상 업스트림으로 안전 폴백, 만료 엔트리는 retention 워커가 정리. 적중 시 `X-Cache-Type: chat-semantic``r`n"
$notes += "- **Text2SQL 어드민 UI 통합 (`v0.5.0`)**: 그동안 API 전용이던 기능들을 어드민 Text2SQL 탭에 노출 — 저장 리포트(스케줄·MM 전달 상태), 인사이트 마이너(반복 질문 → **원클릭 리포트 승격** 버튼, 업무 용어 후보), 행동 이상 탐지(usage smell·팀 누적 위험·intent drift). 운영자가 코드/curl 없이 컨트롤 플레인을 다룰 수 있음`r`n"
$notes += "- **Text2SQL 관측 메트릭 (`v0.4.9`)**: Prometheus(`/metrics`)에 Text2SQL 운영 카운터 추가 — `proxy_text2sql_requests_total`, `_cache_hits_total`, `_risk_blocked_total`, `_challenge_veto_total`, `_shadow_evals_total`. 그동안 추가한 기능들(캐시·위험 차단·self-challenge·shadow)의 실제 발동량을 모니터링 가능`r`n"
$notes += "- **저장 리포트 스케줄 실행 (`v0.4.8`)**: 승격된 saved report에 스케줄(`schedule_interval` 예 24h)·on/off·Mattermost 전달 설정(`POST /admin/text2sql/reports {id,interval,enabled,deliver_mattermost}`) 추가. 백그라운드 스케줄러가 도래한 리포트를 read-only로 실행하고 결과 요약을 Mattermost(`text2sql_report` 이벤트)로 전달 — 반복 질문 자산화의 마지막 단계 완성. 실행 DB(`TEXT2SQL_EXEC_DSN`) 미설정 시 자동 비활성`r`n"
$notes += "- **정책 GitOps export/import (`v0.4.7`)**: 거버넌스 정책+룰을 portable JSON으로 내보내기(`GET /admin/policies/export`)·가져오기(`POST /admin/policies/import`). `?dry_run=1`이면 생성/수정 플랜만 반환(쓰기 없음)하여 repo 커밋·PR 리뷰·diff·롤백 기반 GitOps 운영 가능`r`n"
$notes += "- **ClickHouse 상세 Text2SQL fact 적재 (`v0.4.6`)**: 일별 rollup에 더해 **질의 단위 fact 테이블** 적재(`CLICKHOUSE_TEXT2SQL_FACT_TABLE` 설정 시) — 질문 원문/SQL은 제외(마스킹, question_chars만)하고 team·모델·모드·스키마버전·valid·executed·row_count·EXPLAIN위험·비용·지연·실패분류를 행 단위로 전송. watermark 증분(`text2sql_fact` dimension) + 자동 sink 루프 포함 + 수동 `/admin/dw/text2sql-fact`. 첫 실행은 최근 7일 백필`r`n"
$notes += "- **Text2SQL 응답 품질 강화 (`v0.4.5`)**: 검증 통과 응답에 **감사 근거 푸터**(스키마·버전·permission/glossary 지문·EXPLAIN 위험·마스킹 컬럼) 자동 첨부, 검증 거부 시 **수정 방법 안내**(사유 기반 친화 가이드) 첨부, 실행 결과 0행이면 **결과 없음 복구 제안**(기간·조건·필터 완화) 첨부`r`n"
$notes += "- **Text2SQL 질문 자산화 + 위험 단계화 (`v0.4.4`)**: 반복 질문 원클릭 **승격 API**(`/admin/text2sql/promote` — target=report/golden/glossary; 저장 리포트는 `text2sql_saved_reports` + `/admin/text2sql/reports` 목록/삭제)로 Prompt DNA·리포트 후보를 리포트·골든쿼리·업무 용어 자산으로 전환. 누적 위험 enforce를 **단계화**(감지 < `TEXT2SQL_DAILY_RISK_WARN` ≤ 경고 < `TEXT2SQL_DAILY_RISK_LIMIT` ≤ 차단) — 경고 구간은 응답에 주의 문구만 첨부하고 정상 처리, 차단 구간만 차단`r`n"
$notes += "- **Text2SQL Prompt DNA + 누적 위험 enforce 토글 (`v0.4.3`)**: 질문 지문 분석 **Prompt DNA**(`/admin/text2sql/prompt-dna` — 지문별 빈도·distinct 사용자·평균비용·거부율 집계 + repeated/high_cost/risky 라벨, read-only). 탐지→차단 강제를 위한 **누적 위험 한도 enforce** 토글(`cumulative_risk_enforce` + `TEXT2SQL_DAILY_RISK_LIMIT`, 기본 OFF) — API Key의 당일 위험 요청(거부·고위험 EXPLAIN·실패)이 한도를 넘으면 SQL 생성 전 차단`r`n"
$notes += "- **Text2SQL 기능 토글 + Self Challenge·Gateway Memory (`v0.4.2`)**: 관리자에서 런타임 온오프 가능한 기능 토글 프레임워크(`/admin/text2sql/features`, 어드민 UI 스위치, kill-switch 동일 패널) 추가. 토글로 켜는 신규 기능 — **Self Challenge Proxy**(생성 SQL을 보조 모델이 검토, preview는 의견 첨부·execute는 unsafe 판정 시 실행 보류, 기본 OFF·켜면 요청당 추가 호출), **Gateway Memory**(사용자가 자주 쓰는 테이블을 프롬프트 힌트로 보강, 기본 OFF)`r`n"
$notes += "- **Text2SQL 행동 이상 탐지 (탐지 전용) (`v0.4.1`)**: 차단 없이 운영자 가시성만 제공하는 read-only 탐지(`/admin/text2sql/anomalies`) — **AI Smell Detector**(반복 질문·권한 우회성 거부 반복·스키마 전체 요청), **누적 위험 노출**(팀별 거부·고위험 EXPLAIN·권한 탐침 가중 집계), **Intent Drift Detector**(api_key별 조회→위험/광범위 키워드 이동 감지). 모든 신호는 경고만 하며 요청을 차단하지 않음`r`n"
$notes += "- **Text2SQL 인사이트 마이너 (`v0.4.0`)**: 질문 로그에서 운영 인사이트를 자동 추출하는 read-only 마이너(`/admin/text2sql/miners`) — **Report Candidate Miner**(반복되는 질문을 빈도 집계해 대시보드·배치 리포트 후보로 추천)와 **Glossary Miner**(빈출 질문 토큰 중 스톱워드·기존 정의어를 제외하고 업무 용어 사전 후보 추출). 프록시 호출 비용·사용자 계약 변경 없음`r`n"
$notes += "- **Text2SQL 답변 근거 표시·운영 Kill Switch (`v0.3.9`)**: 응답에 **답변 근거** 섹션 추가(사용한 테이블 + WHERE 적용 조건을 비-SQL 사용자도 검토 가능), 런타임 **Kill Switch**(`/admin/text2sql/kill-switch` — 장애·비용·보안 사고 시 재배포 없이 Text2SQL 즉시 중지, 가상 모델은 안전 메시지 반환)`r`n"
$notes += "- **Text2SQL 민감도 API 보완·DW 점검 강화·비용 분리 (`v0.3.8`)**: 컬럼 민감도 API가 `aggregate_only`·`approval_required`까지 허용(기존 normal/mask/exclude만 → UI 드롭다운과 불일치 수정), Golden Query 결과 동등성 검증을 실행 DB 있을 때 **기본 적용**(`?execute=0`로 해제), ClickHouse 정합성 검증을 **dimension별**(all·model·provider·project·cost_center) 확대, 대상 테이블 **엔진/정렬키 점검 API**(`/admin/dw/table-info` — ReplacingMergeTree·dedupe 키 확인), Text2SQL 비용을 **generation/summary/shadow로 분리** 기록, Replay Bundle **보존 정책(retention GC)·secret 마스킹** 추가`r`n"
$notes += "- **Text2SQL 운영 가시성·재현성 확장 (`v0.3.7`)**: 업무 용어 사전 **충돌 탐지**(동일 용어 복수 매핑·전역/스키마 shadowing을 관리자 화면에서 경고), 위험 요청 큐 **자동 개선 제안**(기간 조건 추가·집계 변경·민감 컬럼 제외·LIMIT 축소 등 수정안 제시), **스키마 변경 영향도 리포트**(`/admin/text2sql/schema-impact` — 버전 변경 시 영향받는 golden·cache·glossary·permission 집계), **Replay Bundle**(opt-in `TEXT2SQL_REPLAY_BUNDLES` — 당시 프롬프트·스키마 컨텍스트·용어사전·권한 스냅샷을 저장해 `/admin/text2sql/replay`로 사후 재현)`r`n"
$notes += "- **Text2SQL shadow 정책 일치·검증기 집계 정확도 (`v0.3.6`)**: shadow 모델 평가가 live와 **동일한 검증 정책**(테이블 allowlist·blocked·aggregate-only)을 적용해 모델 품질 지표를 운영과 일치시킴, 검증기 aggregate-only 판정을 **중첩 괄호 균형 기반**으로 고도화(`sum(coalesce(col,0))` 등 중첩 집계 내 컬럼을 정상 허용, window `OVER(PARTITION BY col)`의 원시 참조는 차단 유지)`r`n"
$notes += "- **Text2SQL 검증 정확도·결과 보호·모델 품질 평가 강화 (`v0.3.5`)**: 컬럼 민감도(`mask`) 기반 **컬럼 단위 결과 마스킹**(선언된 컬럼만 마스킹, 미선언 시 기존 전체 마스킹), 검증기 in-tree **구조 검증**(괄호·따옴표 균형 → 생성 도중 잘린 SQL 차단), 실행 DB **read-only 헬스체크**(`/admin/text2sql/healthcheck` — 연결·read-only 트랜잭션·statement_timeout·계정 쓰기 제한 점검), Golden Query **결과 동등성 평가**(`/admin/text2sql/golden/run?execute=1` — 기대/생성 SQL을 read-only 실행해 행 집합 비교, 토큰 일치를 넘는 의미 검증), **shadow 모델 평가**(`TEXT2SQL_SHADOW_MODELS`·`TEXT2SQL_SHADOW_SAMPLE_RATE` — preview 샘플에서 후보 모델로 비동기 재생성해 모델별 품질 메트릭만 적립, 라이브 KPI 비오염)`r`n"
$notes += "- **Text2SQL 재현성·권한 안전성·DW 적재 신뢰성 강화 (`v0.3.4`)**: Text2SQL 감사 로그에 재현성 필드(schema_name·schema_version·permission_hash·glossary_hash) 추가 — 사후에 ``왜 그 SQL이 생성됐는지`` 당시 스키마·권한·용어사전 상태로 재현 가능. preview 캐시 키에 권한 효과·용어사전 해시를 포함해 **권한이 다른 사용자 간 SQL 재사용 방지**(cross-subject reuse 차단). ClickHouse Sink에 dimension별 watermark(`clickhouse_sink_state`)와 실패 재처리 큐(`clickhouse_sink_retry`) 도입 — 자동 적재 실패가 유실되지 않고 다음 주기/수동 재처리(`/admin/dw/sink-retry`)로 복구, 진행 상태는 `/admin/dw/sink-status` 로 조회`r`n"
$notes += "- **Text2SQL 백로그 완결 — 캐시·버전·민감도·샌드박스·재질문·품질 라우팅·위험 큐·용어사전 (`v0.3.3`)**: preview 결과 캐시(`text2sql_cache`, 질문·스키마·모드·스키마버전 키 + TTL, 스키마 변경 시 자동 무효화), 스키마 버전 관리(version/collected_at/source_fingerprint — 지문 변경 시 자동 증가), 민감도 정책 세분화(`approval_required` 차단 / `aggregate_only` 집계함수 내에서만 허용), 실행 샌드박스 강화(읽기 전용 트랜잭션 + `SET LOCAL statement_timeout`·`work_mem`), 자연어 재질문(clarification) 모드(모호·기간 누락 질문 게이트), 비용·품질 기반 업스트림 자동 선택(기본 모델 유효율 저하 시 정확 모델로 승격), 관리자 위험 요청 큐(`/admin/text2sql/risk-queue` — 거부·고위험 EXPLAIN·실패 분류), 업무 용어 사전(`text2sql_business_terms` — 자연어→SQL 매핑 프롬프트 주입) 추가`r`n"
$notes += "- **Text2SQL 권한·통제·DW 운영화 (`v0.3.2`)**: 권한 매트릭스(`text2sql_permissions` — 팀·API Key·사용자별 schema/table/column allow·deny), 검증기 식별자 추출 강화(quoted/schema-qualified), EXPLAIN 위험도 로그 저장(cost·risk_score), 실패 원인 표준 분류(syntax/permission/cost/timeout/unknown_column/empty), ClickHouse 자동 적재 스케줄러 + 정합성 검증(`/admin/dw/consistency`) 추가`r`n"
$notes += "- **Text2SQL 정확도·운영 통제 심화 (`v0.3.1`)**: 스키마 레지스트리 DB화(테이블/컬럼 + 업무 설명 + 민감도 normal/mask/exclude)와 팀·컬럼 단위 권한 필터, information_schema 자동 수집, 검증기 강화(문자열/주석 리터럴 스크럽), EXPLAIN 위험 점수화(seq scan·nested loop), 현업 친화 응답 포맷(해석/SQL/주의사항/실행여부/다음질문), Text2SQL 품질 평가 emit, Golden Query 자동 후보화, ClickHouse rollup sink(HTTP) 추가`r`n"
$notes += "- **Text2SQL 게이트웨이 및 로드맵 Part 2 완료 (`v0.3.0`)**: 사용자 계약 변경 없이(`/v1/chat/completions` 유지) `vibe/text2sql-*` 가상 모델을 통해 자연어→읽기전용 SQL을 생성하는 Text2SQL 파이프라인 신규 탑재 — 내부에서 실제 업스트림 모델 선택·SQL 검증(SELECT 전용·자동 LIMIT·테이블 권한)·EXPLAIN 비용 가드·결과 PII 마스킹·few-shot 골든쿼리·모델별 SQL 품질 메트릭·DB 스키마 카탈로그/런타임 프로필. 더불어 정책 시뮬레이터(차단 예상 미리보기), 모델 가격표 버전 이력+자동 시드, Mattermost 알림 연계, 팀별 예산 소진 예측, 프롬프트 템플릿 마켓 추가`r`n"
$notes += "- **로드맵 Part 1 완료 및 엔터프라이즈 거버넌스 대대적 확장 (`v0.2.0`)**: Explicit PipelineStep 리팩토링, Ops Health 대시보드 및 주간 AI 리포트 생성, 다차원 비용 할당(Repo/Branch/Project/Service/Cost-Center), CI용 골든 프롬프트 회귀 테스트 게이트, 프롬프트 인젝션 탐지 및 MCP 도구 위험등급 분류, 프로바이더 SLO 모니터링, 월말 비용 예측 및 Operational Risk Score 산출, 폐루프 자동 라우팅 강화 학습, DW 롤업 스태이징 탑재`r`n"
$notes += "- **영속적 세션 추론 및 위임 거버넌스 (`v0.1.26~v0.1.27`)**: 재기동에 안전한 세션 영속 추론 테이블 `inferred_sessions` 추가 및 자동 GC 탑재, team_admin 소속팀 API Key 한정 필터링 조회, 권한 상승(Privilege Escalation) 방지를 위한 계층형 롤/스코프 위임 거버넌스 구현 및 종합 기술 보고서 갱신`r`n"
$notes += "- **사용자 팀 매핑 및 API Key 영구 폐기 관리 (`v0.1.25`)**: 관리자 목록 내 소속 팀 정보 연동 및 패치를 통한 소속 팀 수정·탈퇴 지원, API Key의 개별 세부 권한을 어드민 UI에서 팝업으로 조절 가능한 스코프 편집기 연동, super_admin 한정 키 영구 삭제(?hard=1) 정책 도입`r`n"
